import gzip, os, re, sys
from collections import Counter

IUPAC = {'A':'A','C':'C','G':'G','T':'T','R':'AG','Y':'CT','S':'GC','W':'AT','K':'GT','M':'AC','B':'CGT','D':'AGT','H':'ACT','V':'ACG','N':'ACGT'}
P515 = 'GTGYCAGCMGCCGCGGTAA'
P806 = 'GGACTACNVGGGTWTCTAAT'
COMP = str.maketrans('ACGTNacgtn','TGCANtgcan')

def rc(s):
    return s.translate(COMP)[::-1]

def match_degenerate(seq, primer, max_mm=0):
    if len(seq) < len(primer):
        return False
    mm = 0
    for a,b in zip(seq, primer):
        if a.upper() not in IUPAC.get(b.upper(), ''):
            mm += 1
            if mm > max_mm:
                return False
    return True

def find_primer(seq):
    # exact match first, offsets 0..7; allow fuzzy fallback
    for off in range(0, min(8, max(0, len(seq)-20)+1)):
        if match_degenerate(seq[off:off+20], P515, 0):
            return '515', off + 20, 0
        if match_degenerate(seq[off:off+20], P806, 0):
            return '806', off + 20, 0
    for off in range(0, min(8, max(0, len(seq)-20)+1)):
        if match_degenerate(seq[off:off+20], P515, 1):
            return '515', off + 20, 1
        if match_degenerate(seq[off:off+20], P806, 1):
            return '806', off + 20, 1
    return 'none', None, None

def merge_pair(x, y, minov=180, maxov=220):
    # x and y are both in 515->806 forward orientation
    # find offset of y as suffix of x; resulting length = off + len(y)
    candidates = []
    for off in range(max(0, len(x)-maxov), min(len(x), len(x)-minov)+1):
        ov = min(len(x)-off, len(y))
        if ov < minov:
            continue
        mm = sum(a != b for a,b in zip(x[off:off+ov], y[:ov]))
        outlen = off + len(y)
        if 245 <= outlen <= 260:
            candidates.append((mm, abs(outlen-253), outlen, off, ov))
    if not candidates:
        return None
    # smallest mismatches; among ties, closest to expected length; among ties, larger overlap
    candidates.sort(key=lambda t: (t[0], t[1], -t[4]))
    mm, _, outlen, off, ov = candidates[0]
    if mm > 3:
        return None
    return x[:off] + y, mm, outlen, ov

def read_fastq(path):
