        while True:
            h = f.readline()
            if not h:
                break
            s = f.readline().strip()
            f.readline()
            q = f.readline().strip()
            yield s, q

samples = [line.split('\t')[0] for line in open('/task/input/samples.tsv') if line.strip() and not line.startswith('sample_id')]
summary = {}
for sid in samples:
    r1path = f'/task/input/fastq/{sid}_R1.fastq.gz'
    r2path = f'/task/input/fastq/{sid}_R2.fastq.gz'
    outpath = f'/task/work/merged/{sid}.fasta'
